// Парсинг HTML страницы конкурента
const cheerio = require('cheerio');

// Получаем все входящие данные
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    // Получаем HTML из HTTP Request
    const htmlResponse = item.json.data || item.json.body || '';

    if (!htmlResponse) {
      results.push({
        json: {
          ...item.json,
          parserError: true,
          errorMessage: 'HTML не загружен',
          newPrice: null,
          newDescription: 'Ошибка загрузки HTML'
        }
      });
      continue;
    }

    const $ = cheerio.load(htmlResponse);

    // Получаем данные из Notion
    const notionProps = item.json.properties || {};
    const pageId = item.json.id;
    const title = notionProps.Name?.title?.[0]?.plain_text || 
                  notionProps.Название?.title?.[0]?.plain_text || 
                  notionProps.title?.title?.[0]?.plain_text || 
                  'Без названия';
    const url = notionProps['URL конкурента']?.url || notionProps['URL']?.url || '';
    const previousPrice = notionProps['Последняя цена']?.number || null;
    const previousStatus = notionProps['Последний статус']?.rich_text?.[0]?.plain_text || 'Данных нет';

    // === ВАЖНО: НАСТРОЙТЕ СЕЛЕКТОРЫ ПОД ВАШИ САЙТЫ ===
    // Пример селекторов (замените на реальные):
    let newPrice = null;
    let newDescription = 'Парсинг не удался';
    let parserError = false;

    try {
      // Вариант 1: Попытка найти цену по разным селекторам
      const priceSelectors = [
        '.price',
        '.tour-price',
        '[data-price]',
        '.price-value',
        'span.price',
        'div.price'
      ];

      let priceText = '';
      for (const selector of priceSelectors) {
        priceText = $(selector).first().text().trim();
        if (priceText) break;
      }

      // Извлекаем цену (только цифры)
      if (priceText) {
        const priceMatch = priceText.match(/\d+[\s\d]*/g);
        if (priceMatch) {
          newPrice = parseInt(priceMatch[0].replace(/\s/g, ''));
        }
      }

      // Вариант 2: Попытка найти описание
      const descriptionSelectors = [
        '.description',
        '.tour-description',
        '[data-description]',
        '.content',
        'article',
        '.tour-info'
      ];

      for (const selector of descriptionSelectors) {
        newDescription = $(selector).first().text().trim();
        if (newDescription && newDescription.length > 50) break;
      }

      // Ограничиваем длину описания
      if (newDescription && newDescription.length > 500) {
        newDescription = newDescription.substring(0, 500) + '...';
      }

      if (!newDescription || newDescription.length < 10) {
        newDescription = 'Описание не найдено на странице';
        parserError = true;
      }

      if (!newPrice) {
        parserError = true;
      }

    } catch (parseError) {
      parserError = true;
      console.error('Ошибка парсинга:', parseError.message);
    }

    results.push({
      json: {
        // Новые данные
        newPrice: newPrice,
        newDescription: newDescription,
        parserError: parserError,
        errorMessage: parserError ? 'Не удалось извлечь данные. Проверьте CSS-селекторы.' : null,

        // Старые данные
        previousPrice: previousPrice,
        previousStatus: previousStatus,

        // Метаданные
        pageId: pageId,
        title: title,
        url: url,

        // Дата проверки
        checkDate: new Date().toISOString()
      }
    });

  } catch (error) {
    console.error('Критическая ошибка обработки item:', error);
    results.push({
      json: {
        ...item.json,
        parserError: true,
        errorMessage: error.message,
        newPrice: null,
        newDescription: 'Критическая ошибка обработки'
      }
    });
  }
}

return results;

