// Расчет разницы цен и подготовка данных для отчета
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;

  // Получаем анализ от AI (если есть)
  const aiAnalysis = item.response || item.text || item.content || 'Анализ не выполнен';

  const newPrice = item.newPrice;
  const previousPrice = item.previousPrice;

  let priceDifference = 0;
  let percentageChange = 0;
  let emoji = '🟡';
  let priceChangeText = 'Нет данных о цене';

  if (newPrice !== null && previousPrice !== null) {
    priceDifference = newPrice - previousPrice;
    percentageChange = previousPrice !== 0 ? ((priceDifference / previousPrice) * 100) : 0;

    if (priceDifference > 0) {
      emoji = '📈';
      priceChangeText = `Повышение на ${priceDifference} ₽`;
    } else if (priceDifference < 0) {
      emoji = '📉';
      priceChangeText = `Снижение на ${Math.abs(priceDifference)} ₽`;
    } else {
      emoji = '🟰';
      priceChangeText = 'Без изменений';
    }
  } else if (newPrice !== null && previousPrice === null) {
    emoji = '🆕';
    priceChangeText = 'Первая проверка - данные зафиксированы';
  } else if (newPrice === null) {
    emoji = '❌';
    priceChangeText = 'Цена не найдена';
  }

  results.push({
    json: {
      ...item,
      aiAnalysis: aiAnalysis,
      priceDifference: priceDifference,
      percentageChange: percentageChange.toFixed(2),
      priceEmoji: emoji,
      priceChangeText: priceChangeText
    }
  });
}

return results;

