// Подсчет статистики по всем проверкам
const items = $input.all();

const stats = {
  total: items.length,
  errors: 0,
  changes: 0,
  noChanges: 0,
  priceIncreases: 0,
  priceDecreases: 0
};

items.forEach(item => {
  const data = item.json;

  if (data.parserError) {
    stats.errors++;
  } else if (data.priceDifference > 0) {
    stats.changes++;
    stats.priceIncreases++;
  } else if (data.priceDifference < 0) {
    stats.changes++;
    stats.priceDecreases++;
  } else {
    stats.noChanges++;
  }
});

return [{ json: stats }];

